  function currentOffers(){const a=D.offers(S);a.forEach(o=>S.offerIndex[o.id]=o);return a;}
  function findOffer(id){return S.offerIndex[id]||S.cart.find(o=>o.id===id)||S.saved.find(o=>o.id===id)||currentOffers().find(o=>o.id===id)||window.OpenNEXTExchange?.get(id);}
  const modelQuotes=()=>window.OpenNEXTModelQuotes?.list()||[];
  const findModelQuote=sku=>window.OpenNEXTModelQuotes?.get(sku);
  const tokenMoney=value=>Number.isFinite(Number(value))?Number(value).toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:6}):'Confirm in quote';
  const tokenVolume=value=>Number(value).toLocaleString('en-US',{maximumFractionDigits:6});
  const isModelRFQ=r=>r?.kind==='model_capacity';
  function modelRateSummary(q){return q?`<div class="model-price-grid model-token-rates"><div><small>INPUT / 1M TOKENS</small><strong>${tokenMoney(q.input)}</strong></div><div><small>OUTPUT / 1M TOKENS</small><strong>${tokenMoney(q.output)}</strong></div><div><small>CACHE / 1M TOKENS</small><strong>${tokenMoney(q.cache)}</strong></div></div><p class="form-note">${esc(q.context)} · Cache billing treatment requires quote confirmation.</p>`:'<p class="form-note">Choose a quoted model SKU.</p>';}
