  function collection(type){const items=S[type],name=type==='cart'?'Quote Cart':'Saved Capacity';return `<div class="page-content">${pageHead(name,type==='cart'?'Request quotes directly or compare the suppliers you selected.':'Keep interesting capacity for purchase and comparison.',type==='cart'?button('Request quotes','collection-quotes'):'')}<div class="toolbar"><span class="form-note">${items.length} resources · select up to 4 of the same model</span><span class="gap"></span>${button('Compare selected','compare-selected')}${type==='saved'?button('Add selected to cart','saved-to-cart'):''}</div><div class="collection-grid">${items.map(o=>`<article class="collection-card"><label class="collection-select"><input type="checkbox" data-compare="${o.id}" ${S.selected.includes(o.id)?'checked':''}> Select for comparison</label><div class="row spread"><h3>${esc(o.model)}</h3><strong style="font-size:15px">${money(o.price)}/hr</strong></div><p>${esc(o.provider)} · ${esc(o.region)}<br>${o.count} GPU · ${o.term} · ${o.delivery!=null?o.delivery+' min delivery':'Delivery to confirm'}</p><div class="row">${button('Details','detail',`data-id="${o.id}"`,'secondary small')}${button('Request quote','quote',`data-id="${o.id}"`,'small')}${button('Remove','remove',`data-type="${type}" data-id="${o.id}"`,'ghost small')}</div></article>`).join('')}</div>${items.length?'':empty('Your '+name.toLowerCase()+' is empty','Save or add capacity from the market to start comparing.')}</div>`;}
