  function agent(){return `<aside class="agent-drawer ${S.agentOpen?'open':''}" id="agentDrawer"><div class="drawer-head"><div class="agent-drawer-identity">${agentAvatar("drawer")}<div><strong>OpenNEXT Agent</strong><small>Capacity procurement assistant</small></div></div><button class="icon-btn" data-act="agent-close" aria-label="Close agent">×</button></div><div class="drawer-body" id="agentMessages"><div class="bubble">Tell me the model, region, start time and budget. I can compare suppliers, explain trade-offs and prepare a quote request for your review.</div>${S.agentMessages.map(m=>`<div class="bubble ${m.role==='user'?'user':''}">${esc(m.text).replace(/\n/g,'<br>')}</div>`).join('')}<div class="quick">${['Find the lowest Spot price','Compare best matches','Draft an 8-GPU RFQ'].map(q=>`<button data-act="agent-prompt" data-value="${q}">${q}</button>`).join('')}</div></div><form class="composer" data-form="agent"><input name="message" id="agentInput" placeholder="Ask about capacity…" required><button aria-label="Send message">↑</button></form></aside>`;}
